function setSiteLanguage(language){const column=language==='te'?1:language==='hi'?2:0;document.documentElement.lang=language==='te'?'te-IN':language==='hi'?'hi-IN':'en';for(const [selector,items] of Object.entries(pageCopy)){const nodes=document.querySelectorAll(selector);nodes.forEach((node,index)=>{const entry=items[index]||items[0];if(entry)node.innerHTML=entry[column]})}document.querySelectorAll('.language-switch button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===language)));}
document.querySelectorAll('.language-switch button').forEach(button=>button.addEventListener('click',()=>setSiteLanguage(button.dataset.lang)));



(()=>{const targets=document.querySelectorAll('.hero > div,.trust-strip .trust-pill,.section-head,.service,.story-visual,.story-copy,.city-card,.roadmap-head,.roadmap-card,.model-row > *,.provider-inner > .provider-inner > *,#providers>.provider-inner>*,.step');if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){return}if(!('IntersectionObserver' in window)){return}const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},{threshold:.12,rootMargin:'0px 0px -5% 0px'});targets.forEach((element,index)=>{element.classList.add('reveal');element.style.setProperty('--reveal-delay',String((index%4)*65)+'ms');observer.observe(element)})})();



