const servicePriceEl=serviceDialog.querySelector('.service-price');
const originalShowServiceDetails=showServiceDetails;
showServiceDetails=function(card){originalShowServiceDetails(card);const lang=currentServiceLanguage();const price=servicePriceInfo[card.dataset.service]||'';servicePriceEl.textContent=(lang==='te'?'సూచన ధర: ':lang==='hi'?'संकेतात्मक कीमत: ':'Indicative estimate: ')+price+(lang==='te'?' (తుది ధర కాదు)':'');};
