const areaInput=document.getElementById('bookingArea');const areaList=document.getElementById('bookingAreas');function updateAreaSuggestions(city){const values=areaSuggestions[city]||[];areaList.replaceChildren(...values.map(value=>{const option=document.createElement('option');option.value=value;return option}));areaInput.placeholder=workflowLanguage()==='te'?'ప్రాంతం టైప్ చేయండి (లేదా సూచన ఎంచుకోండి)':workflowLanguage()==='hi'?'इलाका लिखें (या सुझाव चुनें)':'Type an area or choose a suggestion';}citySelect.addEventListener('change',()=>updateAreaSuggestions(citySelect.value));cityCards.forEach(card=>card.addEventListener('click',()=>updateAreaSuggestions(card.dataset.city)));
const extraCopy={
'#trust-details .extras-heading .eyebrow':['Helpful details','ఉపయోగకరమైన వివరాలు','काम की जानकारी'],'#trust-details .extras-heading h2':['More confidence, before you book.','బుక్ చేసే ముందు మరింత స్పష్టత.','बुक करने से पहले पूरी जानकारी।'],'#trust-details .extras-heading p':['Understand the expected process, pricing and professional checks.','సేవా విధానం, ధరలు, నిపుణుల తనిఖీల గురించి తెలుసుకోండి.','सेवा प्रक्रिया, कीमत और पेशेवर जाँच की जानकारी पाएँ।'],
'.trust-detail-card .detail-kicker':[['Booking process','బుకింగ్ విధానం','बुकिंग प्रक्रिया'],['Professional checks','నిపుణుల తనిఖీలు','पेशेवर की जाँच'],['Booking status preview','బుకింగ్ స్థితి ప్రివ్యూ','बुकिंग स्थिति प्रीव्यू'],['Ratings & reviews','రేటింగ్‌లు & సమీక్షలు','रेटिंग और समीक्षाएँ']].map(v=>v),'.trust-detail-card h3':[['From request to done','అభ్యర్థన నుంచి పని పూర్తయ్యే వరకు','अनुरोध से काम पूरा होने तक'],['How verification is intended to work','ధృవీకరణ ఎలా చేయాలని భావిస్తున్నాం','जाँच की प्रस्तावित प्रक्रिया'],['Know what happens next','తర్వాత ఏమవుతుందో తెలుసుకోండి','आगे क्या होगा जानें'],['Feedback from real completed work','పూర్తయిన నిజమైన పనిపై అభిప్రాయం','पूरे हुए असली काम की प्रतिक्रिया']],
'.status-track b':[['Request received','అభ్యర్థన సిద్ధం','अनुरोध मिला'],['Professional confirmation','నిపుణుడి నిర్ధారణ','पेशेवर की पुष्टि'],['Service completed','సేవ పూర్తయింది','सेवा पूरी हुई']],'.status-track span':[['Your service details are ready to review.','మీ సేవా వివరాలు సమీక్షకు సిద్ధంగా ఉన్నాయి.','आपकी सेवा जानकारी समीक्षा के लिए तैयार है।'],['Availability and final scope would be confirmed.','లభ్యత, తుది పనిపరిధి నిర్ధారించబడతాయి.','उपलब्धता और काम की अंतिम सीमा की पुष्टि होगी।'],['Review the work and share feedback.','పనిని సమీక్షించి అభిప్రాయం ఇవ్వండి.','काम की समीक्षा करें और प्रतिक्रिया दें।']],'.booking-steps b':[['1. Request','1. అభ్యర్థన','1. अनुरोध'],['2. Match','2. నిపుణుడి ఎంపిక','2. मिलान'],['3. Complete','3. పని పూర్తి','3. काम पूरा']],'.booking-steps span':[['Choose your city, service, area and preferred time.','నగరం, సేవ, ప్రాంతం, సమయం ఎంచుకోండి.','शहर, सेवा, इलाका और पसंदीदा समय चुनें।'],['A local professional would confirm availability and scope.','స్థానిక నిపుణుడు లభ్యత, పని వివరాలు నిర్ధారిస్తారు.','स्थानीय पेशेवर उपलब्धता और काम की पुष्टि करेंगे।'],['Review the work and payment details after service.','సేవ తర్వాత పని, చెల్లింపు వివరాలు చూడండి.','सेवा के बाद काम और भुगतान की जानकारी देखें।']],'.check-list li':[['Identity and contact details checked','గుర్తింపు, సంప్రదింపు వివరాల తనిఖీ','पहचान और संपर्क विवरण की जाँच'],['Skills and service experience reviewed','నైపుణ్యాలు, అనుభవం పరిశీలన','कौशल और अनुभव की समीक्षा'],['References and completed work considered','రిఫరెన్స్‌లు, చేసిన పనుల పరిశీలన','संदर्भ और पूरे किए काम पर विचार'],['Customer feedback reviewed over time','కస్టమర్ అభిప్రాయాల పరిశీలన','समय के साथ ग्राहक प्रतिक्रिया की समीक्षा']],
'.faq-heading .eyebrow':['Frequently asked questions','తరచూ అడిగే ప్రశ్నలు','अक्सर पूछे जाने वाले सवाल'],' .faq-heading h2':['Good to know.','తెలుసుకోవాల్సిన విషయాలు.','जानना अच्छा है।'],'.faq-item summary':['Are services available in all listed cities?','జాబితాలోని అన్ని నగరాల్లో సేవలు ఉన్నాయా?','क्या सभी शहरों में सेवा उपलब्ध है?','Are the prices final?','ధరలు ఖరారైనవా?','क्या कीमतें अंतिम हैं?','Can I make a real booking or payment here?','ఇక్కడ నిజంగా బుకింగ్ లేదా చెల్లింపు చేయవచ్చా?','क्या यहाँ असली बुकिंग या भुगतान कर सकते हैं?','How are professionals checked?','నిపుణులను ఎలా తనిఖీ చేస్తారు?','पेशेवरों की जाँच कैसे होती है?'],'.faq-item p':['The cities show focus and possible expansion markets. Current service availability is not confirmed.','ఈ నగరాలు ప్రాధాన్య, భవిష్యత్ విస్తరణ ప్రాంతాలు. ప్రస్తుతం సేవల లభ్యత నిర్ధారించలేదు.','ये शहर फोकस और संभावित विस्तार क्षेत्र हैं। अभी सेवा उपलब्ध होने की पुष्टि नहीं है।','No. Price ranges are illustrative estimates for this website preview. A real professional would confirm the scope and final quote.','కాదు. ఇవి వెబ్‌సైట్ ప్రివ్యూ కోసం సూచన ధరలు మాత్రమే. పని వివరాలు చూసి నిపుణుడు తుది ధర చెబుతారు.','नहीं। ये वेबसाइट प्रीव्यू के लिए अनुमान हैं। काम देखकर पेशेवर अंतिम कीमत बताएँगे।','No. This is a front-end demo. Booking requests are not sent or saved, and no payment is processed.','కాదు. ఇది డెమో మాత్రమే. బుకింగ్ పంపబడదు లేదా సేవ్ కాదు; చెల్లింపు జరగదు.','नहीं। यह डेमो है। बुकिंग भेजी या सेव नहीं होती और भुगतान नहीं लिया जाता।','The verification card describes the intended approach. Live onboarding and background checks are not active in this demo.','ధృవీకరణ కార్డ్ ప్రతిపాదిత విధానాన్ని వివరిస్తుంది. ఈ డెమోలో లైవ్ నమోదు లేదా తనిఖీలు లేవు.','जाँच वाला कार्ड प्रस्तावित तरीका बताता है। इस डेमो में लाइव पंजीकरण या जाँच चालू नहीं है।'],
'.contact-strip .detail-kicker':['Have a question?','ప్రశ్న ఉందా?','कोई सवाल है?'],'.contact-strip h3':['Share it on WhatsApp','WhatsApp‌లో సందేశం పంపండి','WhatsApp पर संदेश भेजें'],'.contact-strip p':['Reach us by email or phone, or send a WhatsApp message.','ఈమెయిల్ లేదా ఫోన్‌లో సంప్రదించండి, లేదా WhatsApp సందేశం పంపండి.','ईमेल या फ़ोन से संपर्क करें, या WhatsApp संदेश भेजें।'],'.whatsapp-button':['Open WhatsApp ↗','WhatsApp తెరవండి ↗','WhatsApp खोलें ↗']};
function applyExtraLanguage(language){const col=language==='te'?1:language==='hi'?2:0;for(const [selector,copy] of Object.entries(extraCopy)){document.querySelectorAll(selector.trim()).forEach((node,index)=>{const row=Array.isArray(copy[0])?copy[index]||copy[0]:copy;node.textContent=row[col]||row[0]})}const noteText=language==='te'?'ఇవి ప్రతిపాదిత తనిఖీలు మాత్రమే. ఈ డెమోలో నమోదు చేసిన లేదా ధృవీకరించిన నిపుణులు లేరు.':language==='hi'?'ये प्रस्तावित जाँच हैं। इस डेमो में पंजीकृत या सत्यापित पेशेवर नहीं हैं।':'These are proposed checks. This demo has no registered or verified professionals yet.';document.querySelector('#verification .detail-disclaimer').textContent=noteText;document.querySelector('#booking-flow .detail-disclaimer').textContent=language==='te'?'ఇది ప్రతిపాదిత విధానం మాత్రమే; లైవ్ అభ్యర్థనలు, స్థితి అప్‌డేట్‌లు కనెక్ట్ కాలేదు.':language==='hi'?'यह प्रस्तावित प्रक्रिया है; लाइव अनुरोध और स्थिति अपडेट जुड़े नहीं हैं।':'This is the planned flow; live requests and status updates are not connected.';document.querySelector('#status-preview .detail-disclaimer').textContent=language==='te'?'సూచనాత్మక స్థితి విధానం మాత్రమే. ఈ డెమో నిజమైన బుకింగ్‌ను సృష్టించదు లేదా ట్రాక్ చేయదు.':language==='hi'?'सिर्फ़ उदाहरण के लिए स्थिति प्रक्रिया। यह डेमो असली बुकिंग नहीं बनाता या ट्रैक करता।':'Illustrative status flow only. This demo does not create or track a real booking.';document.querySelector('#reviews .reviews-empty p').textContent=language==='te'?'లైవ్ బుకింగ్‌లు ప్రారంభమైన తర్వాత ధృవీకరించిన కస్టమర్ సమీక్షలు ఇక్కడ కనిపిస్తాయి.':language==='hi'?'लाइव बुकिंग शुरू होने के बाद सत्यापित ग्राहक समीक्षाएँ यहाँ दिखेंगी।':'Verified customer reviews will appear here after live bookings begin.';document.querySelector('#reviews .detail-disclaimer').textContent=language==='te'?'నమూనా రేటింగ్‌లను నిజమైన కస్టమర్ అభిప్రాయాలుగా చూపించడం లేదు.':language==='hi'?'नमूना रेटिंग को असली ग्राहक प्रतिक्रिया की तरह नहीं दिखाया गया है।':'No sample ratings are shown as real customer feedback.';document.querySelectorAll('.faq-item').forEach((item,index)=>{const summary=item.querySelector('summary');const answer=item.querySelector('p');const sums=extraCopy['.faq-item summary'];const ans=extraCopy['.faq-item p'];summary.textContent=sums[index*3+col];answer.textContent=ans[index*3+col]});const share=language==='te'?'నమస్కారం స్వగృహ, గృహ సేవల గురించి ఒక ప్రశ్న ఉంది.':language==='hi'?'नमस्ते स्वगृह, होम सर्विस के बारे में एक सवाल है।':'Hi Swagruha, I have a question about home services.';document.querySelector('.whatsapp-button').href='https://wa.me/919876543210?text='+encodeURIComponent(share);updateAreaSuggestions(citySelect.value)}
document.querySelectorAll('.language-switch button').forEach(button=>button.addEventListener('click',()=>applyExtraLanguage(button.dataset.lang)));applyExtraLanguage(document.documentElement.lang.startsWith('te')?'te':document.documentElement.lang.startsWith('hi')?'hi':'en');

// City picker and marketplace-style service discovery controls.
const cityPickerDialog=document.getElementById('cityPickerDialog');
const cityPickerGrid=document.getElementById('cityPickerGrid');
const currentCityLabel=document.getElementById('currentCityLabel');
const selectedCityStorageKey='swagruha_selected_city_v1';
let selectedHomeCity='';
try{selectedHomeCity=localStorage.getItem(selectedCityStorageKey)||''}catch{}
function syncTopCityLabel(){currentCityLabel.textContent=selectedHomeCity||'Choose city';cityPickerGrid.querySelectorAll('.city-picker-option').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.city===selectedHomeCity)))}
cityPickerGrid.replaceChildren(...Array.from(cityCards,card=>{const button=document.createElement('button');button.type='button';button.className='city-picker-option';button.dataset.city=card.dataset.city;button.setAttribute('aria-pressed','false');const emblem=document.createElement('span');emblem.className='city-picker-emblem';emblem.textContent=card.dataset.city.slice(0,1);const name=document.createElement('span');name.textContent=card.dataset.city;button.append(emblem,name);button.addEventListener('click',()=>{selectedHomeCity=card.dataset.city;selectedCityForBooking=selectedHomeCity;try{localStorage.setItem(selectedCityStorageKey,selectedHomeCity)}catch{}citySelect.value=selectedHomeCity;updateCityChoiceMessage();syncTopCityLabel();cityPickerDialog.close()});return button}));
syncTopCityLabel();
document.getElementById('openCityPicker').addEventListener('click',()=>cityPickerDialog.showModal());
cityPickerDialog.querySelector('.dialog-close').addEventListener('click',()=>cityPickerDialog.close());
cityPickerDialog.addEventListener('click',event=>{if(event.target===cityPickerDialog)cityPickerDialog.close()});
cityCards.forEach(card=>card.addEventListener('click',()=>{selectedHomeCity=card.dataset.city;try{localStorage.setItem(selectedCityStorageKey,selectedHomeCity)}catch{}syncTopCityLabel()}));
citySelect.addEventListener('change',()=>{if(citySelect.value){selectedHomeCity=citySelect.value;try{localStorage.setItem(selectedCityStorageKey,selectedHomeCity)}catch{}syncTopCityLabel()}});
bookingRequestDialog.addEventListener('close',()=>{if(selectedHomeCity){citySelect.value=selectedHomeCity;selectedCityForBooking=selectedHomeCity;updateCityChoiceMessage()}});
function openQuickBooking(serviceKey){document.getElementById('bookingService').value=serviceKey;if(selectedHomeCity){citySelect.value=selectedHomeCity;selectedCityForBooking=selectedHomeCity;updateCityChoiceMessage()}bookingRequestDialog.showModal();document.getElementById('bookingName').focus({preventScroll:true})}
document.querySelectorAll('[data-quick-service]').forEach(button=>button.addEventListener('click',()=>openQuickBooking(button.dataset.quickService)));
const serviceSearchForm=document.getElementById('serviceSearchForm');
const serviceSearchInput=document.getElementById('serviceSearchInput');
serviceSearchForm.addEventListener('submit',event=>{event.preventDefault();const query=serviceSearchInput.value.trim().toLocaleLowerCase();if(!query){serviceSearchInput.focus();return}const serviceCards=Array.from(document.querySelectorAll('.service[data-service]'));const match=serviceCards.find(card=>card.querySelector('h3').textContent.toLocaleLowerCase().includes(query)||card.dataset.service.replaceAll('_',' ').includes(query));if(match){openQuickBooking(match.dataset.service);return}document.getElementById('services').scrollIntoView({behavior:'smooth'});const note=document.querySelector('#services .section-head p');note.textContent='No exact match found. Browse all service categories below.'});

// Account entry points are preview-only until a secure authentication service exists.
const accountDialog=document.getElementById('accountDialog');
const accountTitle=document.getElementById('accountDialogTitle');
const accountStatus=document.getElementById('accountStatus');
const accountTabs=accountDialog.querySelectorAll('[data-account-tab]');
const accountForms=accountDialog.querySelectorAll('[data-account-form]');
function setAccountMode(mode){accountTitle.textContent=mode==='signup'?'Create an account':'Welcome back';accountStatus.textContent='';accountTabs.forEach(tab=>tab.setAttribute('aria-selected',String(tab.dataset.accountTab===mode)));accountForms.forEach(form=>form.hidden=form.dataset.accountForm!==mode)}
document.querySelectorAll('[data-open-account]').forEach(button=>button.addEventListener('click',()=>{setAccountMode(button.dataset.openAccount);accountDialog.showModal();if(nav.classList.contains('open')){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.innerHTML='<span class="menu-symbol" aria-hidden="true">☰</span><span class="menu-label">Menu</span>'}}));
accountTabs.forEach(tab=>tab.addEventListener('click',()=>setAccountMode(tab.dataset.accountTab)));
accountForms.forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();accountStatus.textContent=form.dataset.accountForm==='signup'?'Account signup preview only. No account was created or information saved.':'Login preview only. Account access is not connected.';const password=form.querySelector('[type="password"]');if(password)password.value=''}));
accountDialog.querySelector('.dialog-close').addEventListener('click',()=>accountDialog.close());
accountDialog.addEventListener('click',event=>{if(event.target===accountDialog)accountDialog.close()});
function updateMenuButton(){const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.innerHTML=open?'<span class="menu-symbol" aria-hidden="true">×</span><span class="menu-label">Close</span>':'<span class="menu-symbol" aria-hidden="true">☰</span><span class="menu-label">Menu</span>'}
menuButton.addEventListener('click',updateMenuButton);
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',updateMenuButton));
