serviceSearchForm.addEventListener('submit',event=>{event.preventDefault();event.stopImmediatePropagation();const language=document.documentElement.lang.startsWith('te')?'te':document.documentElement.lang.startsWith('hi')?'hi':'en';const query=serviceSearchInput.value.trim().toLocaleLowerCase();if(!query){serviceSearchInput.focus();return}const cards=Array.from(document.querySelectorAll('.service[data-service]'));const match=cards.find(card=>{const key=card.dataset.service;const terms=[key.replaceAll('_',' '),card.querySelector('h3').textContent.toLocaleLowerCase(),...(translatedServiceTerms[language][key]||[])];return terms.some(term=>term.toLocaleLowerCase().includes(query)||query.includes(term.toLocaleLowerCase()))});if(match){openQuickBooking(match.dataset.service);return}const note=document.querySelector('#services .section-head p');note.textContent=language==='te'?'ఈ సేవకు సరిపోలిక దొరకలేదు. కింద ఉన్న సేవల జాబితా చూడండి.':language==='hi'?'इस सेवा का मेल नहीं मिला। नीचे दी गई सेवाएँ देखें।':'No matching service found. Browse the service list below.';document.getElementById('services').scrollIntoView({behavior:'smooth'})},true);
