const footerLanguageCopy={en:{tag:'A little more at ease, every day.',faq:'FAQs',admin:'Admin dashboard (demo)',disclaimer:'Swagruha is presented here as a home-services marketplace concept. City references are illustrative; availability, bookings and provider onboarding are not live on this website.'},te:{tag:'ప్రతి రోజూ మరింత ప్రశాంతంగా.',faq:'తరచుగా అడిగే ప్రశ్నలు',admin:'అడ్మిన్ డ్యాష్‌బోర్డ్ (డెమో)',disclaimer:'స్వగృహ గృహ సేవల మార్కెట్‌ప్లేస్ కాన్సెప్ట్‌గా చూపబడింది. నగరాలు సూచనాత్మకం మాత్రమే; సేవలు, బుకింగ్‌లు, నిపుణుల నమోదు ఇంకా లైవ్‌లో లేవు.'},hi:{tag:'हर दिन थोड़ा और सुकून।',faq:'अक्सर पूछे जाने वाले प्रश्न',admin:'एडमिन डैशबोर्ड (डेमो)',disclaimer:'स्वगृह को घरेलू सेवाओं के बाज़ार की अवधारणा के रूप में दिखाया गया है। शहर केवल उदाहरण हैं; सेवाएँ, बुकिंग और पेशेवर पंजीकरण अभी चालू नहीं हैं।'}};
