function updateAccessibilityLanguage(language){const te=language==='te',hi=language==='hi';const copy=extendedLanguageCopy[language]||extendedLanguageCopy.en;const close=te?'మూసివేయి':hi?'बंद करें':'Close';document.querySelectorAll('.dialog-close').forEach(node=>node.setAttribute('aria-label',close));const serviceClose=document.querySelector('.service-dialog-close');if(serviceClose)serviceClose.textContent=close;const phone=document.getElementById('bookingPhone');const pin=document.getElementById('bookingPin');if(phone)phone.title=te?'సరైన 10 అంకెల భారతీయ మొబైల్ నంబర్ ఇవ్వండి':hi?'10 अंकों का सही भारतीय मोबाइल नंबर दर्ज करें':'Enter a valid 10-digit Indian mobile number';if(pin)pin.title=te?'6 అంకెల పిన్‌కోడ్ ఇవ్వండి':hi?'6 अंकों का पिनकोड दर्ज करें':'Enter a 6-digit Indian pincode';const skip=document.getElementById('skipIntro');if(skip){skip.textContent=te?'దాటవేయి':hi?'छोड़ें':'Skip intro';skip.setAttribute('aria-label',skip.textContent)}const search=document.getElementById('serviceSearchInput');if(search)search.setAttribute('aria-label',copy.search)}
