const prepTranslations={en:{eyebrow:'A smoother service visit',title:'Get your home ready.',intro:'A few small steps help your local professional get started smoothly.',note:'Helpful suggestions only. This checklist is not required to book.',choose:'Choose a service',clear:'Clear checklist',done:'done',services:{home_cleaning:'Home cleaning',ac_servicing:'AC servicing',painting:'Painting',electrician:'Electrician',plumbing:'Plumbing'},tasks:{home_cleaning:['Clear fragile items from work areas.','Point out rooms or surfaces needing extra attention.','Keep access paths to the rooms open.'],ac_servicing:['Keep the area around the indoor unit accessible.','Keep the remote nearby, if available.','Note unusual sounds or cooling issues.'],painting:['Move small items away from the walls.','Cover furniture and electronics near the work area.','Point out cracks, damp spots or peeling paint.'],electrician:['Identify the switch, appliance or outlet with the issue.','Keep access to the electrical panel clear.','Describe when the problem started.'],plumbing:['Clear the area beneath the sink or around the leak.','Note when and where the leak or blockage happens.','Keep the main water shutoff location in mind.']}},te:{eyebrow:'సేవ మరింత సులభంగా జరిగేందుకు',title:'మీ ఇంటిని సిద్ధం చేసుకోండి.',intro:'కొన్ని చిన్న ఏర్పాట్లు స్థానిక నిపుణులు పనిని సులభంగా ప్రారంభించేందుకు తోడ్పడతాయి.',note:'ఇవి సూచనలు మాత్రమే. బుకింగ్‌కు ఈ చెక్‌లిస్ట్ తప్పనిసరి కాదు.',choose:'సేవను ఎంచుకోండి',clear:'చెక్‌లిస్ట్ క్లియర్ చేయండి',done:'పూర్తి',services:{home_cleaning:'ఇంటి శుభ్రత',ac_servicing:'ఏసీ సర్వీసింగ్',painting:'పెయింటింగ్',electrician:'ఎలక్ట్రీషియన్',plumbing:'ప్లంబింగ్'},tasks:{home_cleaning:['పని చేసే చోట్ల సులభంగా పగిలే వస్తువులు పక్కకు పెట్టండి.','ప్రత్యేక శ్రద్ధ కావాల్సిన గదులు లేదా ఉపరితలాలు చూపండి.','గదులకు వెళ్లే దారిని ఖాళీగా ఉంచండి.'],ac_servicing:['ఇండోర్ యూనిట్ చుట్టూ ఖాళీగా ఉంచండి.','ఉంటే రిమోట్‌ను దగ్గరలో పెట్టండి.','వింత శబ్దాలు లేదా కూలింగ్ సమస్యలను గమనించండి.'],painting:['గోడల దగ్గర చిన్న వస్తువులను పక్కకు జరపండి.','పని ప్రాంతం దగ్గర ఫర్నిచర్, ఎలక్ట్రానిక్స్‌ను కప్పండి.','పగుళ్లు, తడి లేదా ఊడుతున్న రంగు ఉన్న చోట్లను చూపండి.'],electrician:['సమస్య ఉన్న స్విచ్, పరికరం లేదా ప్లగ్‌ను గుర్తించండి.','ఎలక్ట్రికల్ ప్యానెల్ దగ్గరికి వెళ్లే దారిని ఖాళీగా ఉంచండి.','సమస్య ఎప్పుడు మొదలైందో చెప్పండి.'],plumbing:['సింక్ కింద లేదా లీక్ దగ్గర వస్తువులు తొలగించండి.','లీక్ లేదా బ్లాక్ ఎప్పుడు, ఎక్కడ వస్తుందో గమనించండి.','ప్రధాన నీటి వాల్వ్ ఎక్కడుందో గుర్తుంచుకోండి.']}},hi:{eyebrow:'सेवा को आसान बनाने के लिए',title:'अपने घर को तैयार रखें।',intro:'कुछ छोटी तैयारियों से स्थानीय पेशेवर काम आसानी से शुरू कर पाएँगे।',note:'ये केवल सुझाव हैं। बुकिंग के लिए यह चेकलिस्ट ज़रूरी नहीं है।',choose:'सेवा चुनें',clear:'चेकलिस्ट साफ़ करें',done:'पूरे',services:{home_cleaning:'घर की सफ़ाई',ac_servicing:'एसी सर्विसिंग',painting:'पेंटिंग',electrician:'इलेक्ट्रीशियन',plumbing:'प्लंबिंग'},tasks:{home_cleaning:['काम की जगह से नाज़ुक सामान हटा दें।','जिन कमरों या सतहों पर ज़्यादा ध्यान चाहिए, उन्हें बताएँ।','कमरों तक जाने का रास्ता खुला रखें।'],ac_servicing:['इनडोर यूनिट के आसपास जगह खाली रखें।','रिमोट हो तो पास में रखें।','असामान्य आवाज़ या कूलिंग की समस्या नोट करें।'],painting:['दीवारों के पास की छोटी चीज़ें हटा दें।','काम की जगह के पास फर्नीचर और इलेक्ट्रॉनिक्स ढक दें।','दरार, सीलन या उखड़े रंग वाली जगह बताएँ।'],electrician:['समस्या वाला स्विच, उपकरण या सॉकेट पहचानें।','इलेक्ट्रिकल पैनल तक रास्ता खुला रखें।','बताएँ कि समस्या कब शुरू हुई।'],plumbing:['सिंक के नीचे या लीकेज के पास की चीज़ें हटा दें।','लीकेज या जाम कब और कहाँ होता है, नोट करें।','मुख्य पानी का वाल्व कहाँ है, ध्यान रखें।']}}};
let activePrepService='home_cleaning';const prepDone=new Map();function updatePrepChecklist(language){const copy=prepTranslations[language]||prepTranslations.en;document.getElementById('prepEyebrow').textContent=copy.eyebrow;document.getElementById('visitPrepTitle').textContent=copy.title;document.getElementById('prepIntroText').textContent=copy.intro;document.getElementById('prepNote').textContent=copy.note;document.getElementById('prepChooseLabel').textContent=copy.choose;document.getElementById('clearPrepChecklist').textContent=copy.clear;document.querySelectorAll('[data-prep-service]').forEach(tab=>{tab.textContent=copy.services[tab.dataset.prepService];tab.setAttribute('aria-selected',String(tab.dataset.prepService===activePrepService))});const checked=prepDone.get(activePrepService)||new Set();const list=document.getElementById('prepChecklist');list.replaceChildren(...copy.tasks[activePrepService].map((task,index)=>{const li=document.createElement('li');const label=document.createElement('label');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=checked.has(index);const span=document.createElement('span');span.textContent=task;checkbox.addEventListener('change',()=>{const next=prepDone.get(activePrepService)||new Set();checkbox.checked?next.add(index):next.delete(index);prepDone.set(activePrepService,next);updatePrepProgress(language)});label.append(checkbox,span);li.append(label);return li}));updatePrepProgress(language)}function updatePrepProgress(language){const copy=prepTranslations[language]||prepTranslations.en;const selected=prepDone.get(activePrepService)||new Set();const total=copy.tasks[activePrepService].length;document.getElementById('prepProgressLabel').textContent=language==='te'?total+'లో '+selected.size+' '+copy.done:language==='hi'?total+' में से '+selected.size+' '+copy.done:selected.size+' of '+total+' '+copy.done;document.getElementById('prepProgressBar').style.width=(total?selected.size/total*100:0)+'%'}document.querySelectorAll('[data-prep-service]').forEach(tab=>tab.addEventListener('click',()=>{activePrepService=tab.dataset.prepService;updatePrepChecklist(document.documentElement.lang.startsWith('te')?'te':document.documentElement.lang.startsWith('hi')?'hi':'en')}));document.getElementById('clearPrepChecklist').addEventListener('click',()=>{prepDone.set(activePrepService,new Set());updatePrepChecklist(document.documentElement.lang.startsWith('te')?'te':document.documentElement.lang.startsWith('hi')?'hi':'en')});document.querySelectorAll('.language-switch button').forEach(button=>button.addEventListener('click',()=>updatePrepChecklist(button.dataset.lang)));updatePrepChecklist(document.documentElement.lang.startsWith('te')?'te':document.documentElement.lang.startsWith('hi')?'hi':'en');
updatePrepProgress=function(language){const copy=prepTranslations[language]||prepTranslations.en;const selected=prepDone.get(activePrepService)||new Set();const total=copy.tasks[activePrepService].length;document.getElementById('prepProgressLabel').textContent=language==='te'?selected.size+'/'+total+' పూర్తయ్యాయి':language==='hi'?selected.size+'/'+total+' पूरे':selected.size+' of '+total+' done';document.getElementById('prepProgressBar').style.width=(total?selected.size/total*100:0)+'%'};
function updatePrepAccessibility(language){const text=language==='te'?'సేవ కోసం సిద్ధమయ్యే అంశాలను ఎంచుకోండి':language==='hi'?'सेवा की तैयारी के लिए काम चुनें':'Choose a service to prepare for';document.querySelector('.prep-service-tabs').setAttribute('aria-label',text)}
document.querySelectorAll('.language-switch button').forEach(button=>button.addEventListener('click',()=>updatePrepAccessibility(button.dataset.lang)));
updatePrepChecklist(document.documentElement.lang.startsWith('te')?'te':document.documentElement.lang.startsWith('hi')?'hi':'en');
